import{_ as s,a0 as i,w as o,s as p,ao as d,I as n,x as e,a1 as t,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const N=JSON.parse('{"title":"LNAV：基于 Ncurses 的日志文件阅读器 | LCTT x X-CMD","titleTemplate":false,"description":"LNAV：基于 Ncurses 的日志文件阅读器 | LCTT (201512) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"LNAV：基于 Ncurses 的日志文件阅读器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"LNAV：基于 Ncurses 的日志文件阅读器 | LCTT (201512) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201512/20151123 LNAV--Ncurses based log file viewer","title":"LNAV：基于 Ncurses 的日志文件阅读器","tag":"201512","desc":""},"relativePath":"201512/20151123 LNAV--Ncurses based log file viewer.md","filePath":"[post].md"}'),u={name:"201512/20151123 LNAV--Ncurses based log file viewer.md"};function h(b,a,m,f,c,v){const r=i("Link");return o(),p("div",null,[a[13]||(a[13]=d(`<h1 id="lnav-基于-ncurses-的日志文件阅读器" tabindex="-1">LNAV：基于 Ncurses 的日志文件阅读器 <a class="header-anchor" href="#lnav-基于-ncurses-的日志文件阅读器" aria-label="Permalink to “LNAV：基于 Ncurses 的日志文件阅读器”">​</a></h1><p>日志文件导航器（Logfile Navigator，简称 lnav），是一个基于 curses 的，用于查看和分析日志文件的工具。和文本阅读器/编辑器相比， lnav 的好处是它充分利用了可以从日志文件中获取的语义信息，例如时间戳和日志等级。利用这些额外的语义信息， lnav 可以处理像这样的事情：来自不同文件的交错的信息；按照时间生成信息直方图；支持在文件中导航的快捷键。它希望使用这些功能可以使得用户可以快速有效地定位和解决问题。</p><h3 id="lnav-功能" tabindex="-1">lnav 功能 <a class="header-anchor" href="#lnav-功能" aria-label="Permalink to “lnav 功能”">​</a></h3><h4 id="支持以下日志文件格式" tabindex="-1">支持以下日志文件格式： <a class="header-anchor" href="#支持以下日志文件格式" aria-label="Permalink to “支持以下日志文件格式：”">​</a></h4><p>Syslog、Apache 访问日志、strace、tcsh 历史以及常见的带时间戳的日志文件。读入文件的时候回自动检测文件格式。</p><h4 id="直方图视图" tabindex="-1">直方图视图： <a class="header-anchor" href="#直方图视图" aria-label="Permalink to “直方图视图：”">​</a></h4><p>以时间区划来显示日志信息数量。这对于大概了解在一长段时间内发生了什么非常有用。</p><h4 id="过滤器" tabindex="-1">过滤器： <a class="header-anchor" href="#过滤器" aria-label="Permalink to “过滤器：”">​</a></h4><p>只显示那些匹配或不匹配一些正则表达式的行。对于移除大量你不感兴趣的日志行非常有用。</p><h4 id="即时操作" tabindex="-1">即时操作： <a class="header-anchor" href="#即时操作" aria-label="Permalink to “即时操作：”">​</a></h4><p>在你输入到时候会同时完成检索；当添加了新日志行的时候会自动加载和搜索；加载行的时候会应用过滤器；另外，还会在你输入 SQL 查询的时候检查其正确性。</p><h4 id="自动显示后文" tabindex="-1">自动显示后文： <a class="header-anchor" href="#自动显示后文" aria-label="Permalink to “自动显示后文：”">​</a></h4><p>日志文件视图会自动往下滚动到新添加到文件中的行。只需要向上滚动就可以锁定当前视图，然后向下滚动到底部恢复显示后文。</p><h4 id="按照日期顺序排序行" tabindex="-1">按照日期顺序排序行： <a class="header-anchor" href="#按照日期顺序排序行" aria-label="Permalink to “按照日期顺序排序行：”">​</a></h4><p>从所有文件中加载的日志行会按照日期进行排序。使得你不需要手动从不同文件中收集日志信息。</p><h4 id="语法高亮" tabindex="-1">语法高亮： <a class="header-anchor" href="#语法高亮" aria-label="Permalink to “语法高亮：”">​</a></h4><p>错误和警告会用红色和黄色显示。高亮还可用于： SQL 关键字、XML 标签、Java 文件行号和括起来的字符串。</p><h4 id="导航" tabindex="-1">导航： <a class="header-anchor" href="#导航" aria-label="Permalink to “导航：”">​</a></h4><p>有快捷键用于跳转到下一个或上一个错误或警告，按照指定的时间向后或向前翻页。</p><h4 id="用-sql-查询日志" tabindex="-1">用 SQL 查询日志： <a class="header-anchor" href="#用-sql-查询日志" aria-label="Permalink to “用 SQL 查询日志：”">​</a></h4><p>每个日志文件行都相当于数据库中的一行，可以使用 SQL 进行查询。可以使用的列取决于查看的日志文件类型。</p><h4 id="命令和搜索历史" tabindex="-1">命令和搜索历史：　#### <a class="header-anchor" href="#命令和搜索历史" aria-label="Permalink to “命令和搜索历史：　####”">​</a></h4><p>会自动保存你之前输入的命令和搜素，因此你可以在会话之间使用它们。</p><p>####　压缩文件： ####</p><p>会实时自动检测和解压压缩的日志文件。</p><h3 id="在-ubuntu-15-10-上安装-lnav" tabindex="-1">在 ubuntu 15.10 上安装 lnav <a class="header-anchor" href="#在-ubuntu-15-10-上安装-lnav" aria-label="Permalink to “在 ubuntu 15.10 上安装 lnav”">​</a></h3><p>打开终端运行下面的命令</p><pre><code>sudo apt-get install lnav
</code></pre><h3 id="使用-lnav" tabindex="-1">使用 lnav <a class="header-anchor" href="#使用-lnav" aria-label="Permalink to “使用 lnav”">​</a></h3><p>如果你想使用 lnav 查看日志，你可以使用下面的命令，默认它会显示 syslogs</p><pre><code>lnav
</code></pre><p><img src="http://www.ubuntugeek.com/wp-content/uploads/2015/11/51.png" alt=""></p><p>如果你想查看特定的日志，那么需要指定路径。如果你想看 CPU 日志，在你的终端里运行下面的命令</p><pre><code>lnav /var/log/cups
</code></pre><p><img src="http://www.ubuntugeek.com/wp-content/uploads/2015/11/6.png" alt=""></p><hr>`,36)),n("p",null,[a[1]||(a[1]=e("via: ",-1)),t(r,{href:"http://www.ubuntugeek.com/lnav-ncurses-based-log-file-viewer.html"},{default:l(()=>[...a[0]||(a[0]=[e("http://www.ubuntugeek.com/lnav-ncurses-based-log-file-viewer.html",-1)])]),_:1})]),n("p",null,[a[5]||(a[5]=e("作者：",-1)),t(r,{href:"http://www.ubuntugeek.com/author/ubuntufix"},{default:l(()=>[...a[2]||(a[2]=[e("ruchi",-1)])]),_:1}),a[6]||(a[6]=e(" 译者：",-1)),t(r,{href:"http://mutouxiaogui.cn/blog/"},{default:l(()=>[...a[3]||(a[3]=[e("ictlyh",-1)])]),_:1}),a[7]||(a[7]=e(" 校对：",-1)),t(r,{href:"https://github.com/wxy"},{default:l(()=>[...a[4]||(a[4]=[e("wxy",-1)])]),_:1})]),n("p",null,[a[10]||(a[10]=e("本文由 ",-1)),t(r,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...a[8]||(a[8]=[e("LCTT",-1)])]),_:1}),a[11]||(a[11]=e(" 原创编译，",-1)),t(r,{href:"https://linux.cn/"},{default:l(()=>[...a[9]||(a[9]=[e("Linux中国",-1)])]),_:1}),a[12]||(a[12]=e(" 荣誉推出",-1))])])}const L=s(u,[["render",h]]);export{N as __pageData,L as default};
